module tb_qwen2_kv_append_ddr_page_core;
 logic clk=0,rst_n=0,start,pv,pr,pl,pvalid,iv,ir,rv,rr,re,done;always #0.5 clk=~clk;logic[9:0]pi;logic[31:0]pp,pg,pc;logic[63:0]is,id;logic[31:0]il;logic[7:0]status;logic[31:0]pu,reqs;logic[63:0]bytes;logic[31:0]lfsr;integer ptes,dmas,pages_seen;logic[63:0]pending_src,pending_dst;logic pending;
 qwen2_kv_append_ddr_page_core dut(.clk_i(clk),.rst_ni(rst_n),.start_i(start),.k_address_i(64'h201000000),.v_address_i(64'h201100000),.data_address_i(64'h500008000),.token_start_i(0),.token_count_i(1024),.generation_i(0),.logical_page_count_i(64),.physical_page_limit_i(4096),.page_tokens_log2_i(4),.pte_valid_o(pv),.pte_ready_i(pr),.pte_level_o(pl),.pte_index_o(pi),.pte_physical_page_o(pp),.pte_generation_o(pg),.pte_refcount_o(pc),.pte_entry_valid_o(pvalid),.idma_req_valid_o(iv),.idma_req_ready_i(ir),.idma_src_addr_o(is),.idma_dst_addr_o(id),.idma_length_o(il),.idma_rsp_valid_i(rv),.idma_rsp_ready_o(rr),.idma_rsp_error_i(re),.done_o(done),.status_o(status),.pte_updates_o(pu),.idma_requests_o(reqs),.payload_bytes_o(bytes));
 assign pr=lfsr[0]||lfsr[4];assign ir=!pending&&(lfsr[1]||lfsr[7]);assign rv=pending&&(lfsr[2]||lfsr[9]);assign re=0;
 always_ff@(posedge clk or negedge rst_n)begin if(!rst_n)begin lfsr<=32'h5eed1234;ptes<=0;dmas<=0;pages_seen<=0;pending<=0;pending_src<=0;pending_dst<=0;end else begin lfsr<={lfsr[30:0],lfsr[31]^lfsr[21]^lfsr[1]^lfsr[0]};if(pv&&pr)begin if(!pvalid||pg!=0||pc!=1)$fatal(1,"pte common");if(ptes==0)begin if(pl||pi!=0||pp!=0)$fatal(1,"root");end else begin if(!pl||pi!=ptes-1||pp!=ptes-1)$fatal(1,"leaf ptes=%0d pi=%0d pp=%0d",ptes,pi,pp);pages_seen<=pages_seen+1;end ptes<=ptes+1;end if(iv&&ir)begin if(il!=8192)$fatal(1,"length");if((dmas&1)==0)begin if(is!=64'h201000000+(dmas/2)*8192||id!=64'h500008000+(dmas/2)*16384)$fatal(1,"K dma=%0d src=%h dst=%h",dmas,is,id);end else if(is!=64'h201100000+(dmas/2)*8192||id!=64'h500008000+(dmas/2)*16384+8192)$fatal(1,"V dma=%0d src=%h dst=%h",dmas,is,id);pending<=1;pending_src<=is;pending_dst<=id;dmas<=dmas+1;end if(rv&&rr)pending<=0;end end
 initial begin start=0;repeat(5)@(posedge clk);rst_n=1;@(negedge clk);start=1;@(posedge clk);@(negedge clk);start=0;wait(done);if(status!=0||ptes!=65||pages_seen!=64||dmas!=128||pu!=65||reqs!=128||bytes!=1048576||pending)$fatal(1,"aggregate status=%0d ptes=%0d pages=%0d dmas=%0d pu=%0d reqs=%0d bytes=%0d pending=%0d",status,ptes,pages_seen,dmas,pu,reqs,bytes,pending);$display("QWEN2_KV_APPEND_DDR_PAGE_CORE_PASS pte_updates=65 root=1 leaf=64 idma_requests=128 payload_bytes=1048576 pages=64 page_bytes=16384 K_bytes=524288 V_bytes=524288 random_backpressure=1");$finish;end
